head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vs_G_Std_Cd = "";
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
scwin.processGp;
scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        /**********************************************
         * 함수명   : gform > onload
         * 설명      : 화면 Onload
         ***********************************************/
        $c.bns.BnsPanelToGroupBox(panel_Top);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS25300.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        /**********************************************
         * Event   : btn_Search > OnClick
         * 설명    : 조회버튼 클릭
         ***********************************************/
        // 조회
        await scwin.listSearch();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS25300.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    try {
        /**********************************************
         * Event   : img_com_srch > OnClick
         * 설명    : 발행기관 조회팝업
         ***********************************************/
        scwin.fn_GetPar = scwin.getParInst;
        scwin.fn_SetPar = scwin.setParInst;
        $c.bns.fn_PopInstSearch(img_com_srch);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS25300.img_com_srch_onclick" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    try {
        /**********************************************
         * 함수명   : txb_ISUR_CD > onblur
         * 설명      : 발행기관 코드 변경
         ***********************************************/
        if (txb_isur_cd.getValue() === "") {
            txb_com_abbrv.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS25300.txb_isur_cd_onblur" });
    }
};

/**
 * @method
 * @name dts_List_1_OnLoadError
 * @description dts_List_1 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_1_OnLoadError = async function() {
    try {
        /**********************************************
         * Event   : dts_List_1 > OnLoadError
         * 설명    : dts_List_1 조회에러시 처리
         ***********************************************/
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS25300.dts_List_1_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_1_OnLoadCompleted
 * @description dts_List_1 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_1_OnLoadCompleted = function(rowcount) {
    try {
        /**********************************************
         * Event   : dts_List_1 > OnLoadCompleted
         * 설명    : dts_List_1 조회성공시 처리
         ***********************************************/
        dts_List_1.setRowPosition(0, 0);
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS25300.dts_List_1_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_2_OnLoadError
 * @description dts_List_2 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_2_OnLoadError = async function() {
    try {
        /**********************************************
         * Event   : dts_List_2 > OnLoadError
         * 설명    : dts_List_2 조회에러시 처리
         ***********************************************/
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS25300.dts_List_2_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_2_OnLoadCompleted
 * @description dts_List_2 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_2_OnLoadCompleted = function(rowcount) {
    try {
        /**********************************************
         * Event   : dts_List_2 > OnLoadCompleted
         * 설명    : dts_List_2 조회성공시 처리
         ***********************************************/
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page2);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS25300.dts_List_2_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_1_OnRowPosChanged
 * @description List 1 On Row Pos Changed 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_1_OnRowPosChanged = async function(row) {
    try {
        /**********************************************
         * Event   : dts_List_1 > OnRowPosChanged
         * 설명    : 그리드 위치 변경시 세팅
         ***********************************************/
        if (row === 0) return;
        await scwin.searchDetail(row);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS25300.dts_List_1_OnRowPosChanged" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        /**********************************************
         * Event   : btn_Excel > onclick
         * 설명    : 엑셀버튼클릭
         ***********************************************/
        // 엑셀 로그
        $c.stf.doLogSave("ULDBNS25300.xml", SCREN_PROCS_TP_CD_07);
        const fileNm = $c.session.getExcelDownPath() + $c.ut.cGetToday("yyyymmddhhmmss") + "_보증기관조회.xls";
        $c.data.downloadGridViewExcel(grd_List2, {fileName: "보증기관조회", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS25300.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name grd_List2_OnDblClick
 * @description grd_List2 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List2_OnDblClick = function(row, colid) {
    try {
        /**********************************************
         * Event   : grd_List2 > OnDblClick
         * 설명    : 종목그리드 더블클릭시 상세정보 팝업 호출
         ***********************************************/
        if (row === 0) return;
        scwin.vs_G_Std_Cd = dts_List_2.getCellData(row, "STD_CD");
        scwin.fn_GetPar = scwin.getParIsuDelInfo;
        $c.bns.fn_PopIsuDetail(grd_List1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS25300.grd_List2_OnDblClick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSearch
 * @description 보증기관조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSearch = async function() {
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_INST_SRCH_LIST";
    url += "&queryId=lds.stf.bnslistsrchl.select.instlist";
    url += "&SCREN_ID=" + "ULDBNS25300.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_INST_NM=" + txb_com_abbrv.getValue(); //
    url += "&{P}V_INST_STAT_CD=" + cmb_sch_stat_cd.getValue(); //

    const sbmOptions = {
        id : "sbm_dts_List_1",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List_1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    return url;
};

/**
 * @method
 * @name searchDetail
 * @description 보증기관 상세조회
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchDetail = async function(row) {
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_INST_SRCH_LIST_DETAIL";
    url += "&queryId=lds.stf.bnslistsrchl.select.instlistdetail";
    url += "&SCREN_ID=" + "ULDBNS25300.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_INST_CD=" + dts_List_1.getCellData(row, "BND_INST_CD"); //

    const sbmOptions = {
        id : "sbm_dts_List_2",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List_2=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    return url;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParInst
 * @description 기관 팝업에 넘길 데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParInst = function(arrPar) {
    arrPar[0] = {
        INST_CD: txb_isur_cd.getValue(),
        INST_NM: txb_com_abbrv.getValue(),
        LBL_NM: '',
        INIT_TP_CD: "2"
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParInst
 * @description 기관 팝업에서 받은 데이터를 설정한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParInst = function(arrPar) {
    if (typeof(arrPar[0].INST_CD) !== 'undefined') {
        txb_isur_cd.setValue(arrPar[0].INST_CD);
        txb_com_abbrv.setValue(arrPar[0].INST_NM);
    }
};

/**
 * @method
 * @name getParIsuDelInfo
 * @description 종목상세 목록 팝업에 넘길 데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsuDelInfo = function(arrPar) {
    arrPar[0] = {
        STD_CD: scwin.vs_G_Std_Cd
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};
